import {watchPanel,mountWatch} from './watch.js';
import {readingSets,listeningSets,levels,answerMatches} from './practice-library.js';
import {createPronunciation} from './pronunciation.js';
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let level='all',selected={},timer=null,elapsed=0,paused=false,account='',kindNow='',answers={},zoom=1;
const $=s=>document.querySelector(s);
const audio=createPronunciation({getPreferences:()=>({accent:'en-GB',rate:Number($('#studio-rate')?.value)||1}),onError:message=>{if($('#studio-status'))$('#studio-status').textContent=message;}});
export function leaveStudio(){clearInterval(timer);timer=null;audio.stop();}
const sets=k=>k==='reading'?readingSets:listeningSets;
function key(){return 'lexora.practice.'+account+'.'+kindNow+'.'+selected[kindNow];}
function save(){try{localStorage.setItem(key(),JSON.stringify({answers,elapsed}));}catch{}}
export function studioView(kind){
 if(kind==='watch')return `<div class="page-heading"><div><span class="eyebrow">KONTEKSTDA O‘RGANING</span><h1>Watch & learn</h1><p>So‘zning haqiqiy nutqda qanday ishlatilishini toping.</p></div></div><section class="studio-paper context-search"><h2>Bir so‘z. Turli vaziyatlar.</h2><form id="context-search"><label>Inglizcha so‘z yoki ibora<input name="word" maxlength="120" required placeholder="Masalan: look forward to"></label><button class="btn primary">Videolardan topish</button></form><p class="help-text">YouGlish yangi oynada ochiladi. Video va subtitrlarni o‘sha xizmat taqdim etadi.</p><div id="context-links" aria-live="polite"></div></section>${watchPanel()}<div class="studio-catalog">${[['A1–A2','Kundalik suhbat','How are you'],['B1–B2','Fikrni tushuntirish','in my opinion'],['B2–C1','Tabiiy birikmalar','take into account']].map(([l,t,w])=>`<a class="studio-choice" href="https://youglish.com/pronounce/${encodeURIComponent(w)}/english" target="_blank" rel="noopener noreferrer"><span class="tag">${l}</span><h2>${t}</h2><p>${w}</p><span>YouGlish’da ko‘rish</span></a>`).join('')}</div>`;
 const bank=sets(kind),set=bank.find(x=>x.id===selected[kind]),title=kind==='reading'?'Reading':'Listening';
 const header=`<div class="page-heading"><div><span class="eyebrow">MUSTAQIL MASHQ · A1–C1</span><h1>${title} library</h1><p>Darajangizdan boshlang. O‘z sur’atingizda mashq qiling.</p></div>${set?'<button class="btn" id="studio-back">Kutubxona</button>':''}</div>`;
 if(!set)return header+`<details class="studio-paper"><summary>To‘liq IELTS testlari</summary><p>Cambridge to‘plamlari va to‘liq testlar asl manbada ochiladi. Lexora natijani u yerdan avtomatik olmaydi.</p><a class="btn" target="_blank" rel="noopener noreferrer" href="https://engnovate.com/ielts-${kind}-tests/">Engnovate · ${title} testlar</a>${kind==='reading'?'<a class="btn" target="_blank" rel="noopener noreferrer" href="https://engnovate.com/ielts-reading-tests/cambridge-ielts-21-academic-reading-test-1/">Cambridge IELTS 21 · Test 1</a>':''}</details><label class="level-filter">Daraja<select id="studio-level"><option value="all">Barcha darajalar</option>${levels.map(l=>`<option ${l===level?'selected':''}>${l}</option>`).join('')}</select></label><div class="studio-catalog">${bank.filter(s=>level==='all'||s.level===level).map(s=>`<button class="studio-choice" data-studio-id="${s.id}"><span class="tag">${s.level}</span><h2>${s.title}</h2><p>${s.questions.length} savol · ${s.minutes} daqiqa tavsiya etiladi</p><span>Mashqni ochish</span></button>`).join('')}</div><p class="help-text">Lexora uchun yozilgan mustaqil mashqlar. Darajalar yo‘nalish beradi; bu rasmiy IELTS testi yoki CEFR sertifikati emas.</p>`;
 return header+`<div class="studio-toolbar"><span class="tag">${set.level}</span><b>${set.title}</b><output id="studio-clock" aria-label="Mashq vaqti">00:00</output><button class="btn" id="studio-pause" aria-pressed="false">Vaqtni to‘xtatish</button><label>Matn o‘lchami<select id="studio-zoom">${[1,1.15,1.3,1.5].map(n=>`<option value="${n}" ${zoom===n?'selected':''}>${Math.round(n*100)}%</option>`).join('')}</select></label></div><div class="studio-layout independent-studio" style="--reading-scale:${zoom}"><section class="studio-paper passage-pane" aria-label="${title} materiali"><h2>${set.title}</h2>${kind==='reading'?`<div class="reading-passage" id="studio-passage">${set.text.split('\n').map(p=>`<p>${e(p)}</p>`).join('')}</div><button class="btn" id="studio-highlight">Tanlangan matnni belgilash</button><button class="btn" id="studio-clear">Belgilarni tozalash</button>`:`<div class="listen-player"><button class="btn primary" id="studio-play">Tinglash</button><button class="btn" id="studio-stop">To‘xtatish</button><label>Tezlik<select id="studio-rate"><option value="0.7">0.7×</option><option value="0.85">0.85×</option><option value="1" selected>1×</option><option value="1.15">1.15×</option></select></label></div><p class="help-text">Qurilmaning inglizcha ovozi bilan o‘qiladi; studiyada yozilgan audio emas.</p><details><summary>Transcript</summary><p class="reading-passage">${e(set.text)}</p></details>`}<p id="studio-status" role="status"></p></section><section class="studio-paper questions-pane"><h2>Savollar</h2><form id="studio-quiz">${set.questions.map((q,i)=>`<fieldset id="practice-q${i}"><legend>${i+1}. ${e(q.prompt)}</legend>${q.options?q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" ${String(answers['q'+i])===String(j)?'checked':''} required>${e(o)}</label>`).join(''):`<label>Bir yoki ikki so‘z / raqam<input name="q${i}" value="${e(answers['q'+i]||'')}" maxlength="80" required autocomplete="off"></label>`}</fieldset>`).join('')}<div class="buttons"><button class="btn primary">Tekshirish va izohlar</button><button class="btn" id="studio-reset" type="button">Qayta boshlash</button></div><p class="help-text">Javoblar shu qurilmada saqlanadi. Guruh bahosiga ta’sir qilmaydi.</p><div id="studio-result" role="status" tabindex="-1"></div></form></section></div>`;
}
export function mountStudio(kind,accountId){kindNow=kind;account=accountId||'guest';
 const draw=()=>{leaveStudio();$('#app').innerHTML=studioView(kind);mountStudio(kind,account);};
 if(kind==='watch'){mountWatch(account);$('#context-search').onsubmit=ev=>{ev.preventDefault();const word=new FormData(ev.target).get('word').trim();$('#context-links').innerHTML=`<a class="btn primary" target="_blank" rel="noopener noreferrer" href="https://youglish.com/pronounce/${encodeURIComponent(word)}/english">${e(word)} — kontekstda ko‘rish</a>`;};return;}
 $('#studio-level')?.addEventListener('change',ev=>{level=ev.target.value;draw();});
 document.querySelectorAll('[data-studio-id]').forEach(b=>b.onclick=()=>{selected[kind]=b.dataset.studioId;answers={};elapsed=0;paused=false;try{const saved=JSON.parse(localStorage.getItem(key())||'{}');answers=saved.answers||{};elapsed=Number(saved.elapsed)||0;}catch{}draw();});
 const set=sets(kind).find(s=>s.id===selected[kind]);if(!set)return;
 $('#studio-back').onclick=()=>{save();selected[kind]=null;draw();};
 const clock=()=>{if($('#studio-clock'))$('#studio-clock').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(elapsed%60).padStart(2,'0');};clock();
 timer=setInterval(()=>{if(!paused){elapsed++;clock();if(elapsed%10===0)save();}},1000);
 $('#studio-pause').onclick=ev=>{paused=!paused;ev.target.textContent=paused?'Vaqtni davom ettirish':'Vaqtni to‘xtatish';ev.target.setAttribute('aria-pressed',String(paused));save();};
 $('#studio-zoom').onchange=ev=>{zoom=Number(ev.target.value);$('.independent-studio').style.setProperty('--reading-scale',zoom);};
 $('#studio-quiz').onchange=ev=>{answers=Object.fromEntries(new FormData(ev.currentTarget));save();};
 $('#studio-quiz').onsubmit=ev=>{ev.preventDefault();answers=Object.fromEntries(new FormData(ev.target));save();paused=true;$('#studio-pause').textContent='Vaqtni davom ettirish';$('#studio-pause').setAttribute('aria-pressed','true');const checks=set.questions.map((q,i)=>q.options?String(q.answer)===answers['q'+i]:answerMatches(answers['q'+i],q.answer));$('#studio-result').innerHTML=`<h3>${checks.filter(Boolean).length} / ${checks.length} to‘g‘ri</h3>${set.questions.map((q,i)=>`<div class="practice-explanation"><b>${checks[i]?'To‘g‘ri':'Qayta ko‘ring'} · ${i+1}</b><p>Javob: ${e(q.options?q.options[q.answer]:q.answer)}</p><p>${e(q.why)}</p></div>`).join('')}`;$('#studio-result').focus();};
 $('#studio-reset').onclick=()=>{answers={};elapsed=0;paused=false;save();draw();};
 if(kind==='listening'){$('#studio-play').onclick=()=>audio.speak(set.text);$('#studio-stop').onclick=()=>audio.stop();}
 else{$('#studio-highlight').onclick=()=>{const sel=window.getSelection();if(!sel?.rangeCount||!$('#studio-passage').contains(sel.anchorNode)||!$('#studio-passage').contains(sel.focusNode)||sel.isCollapsed){$('#studio-status').textContent='Avval matndan bir parcha tanlang.';return;}const range=sel.getRangeAt(0),mark=document.createElement('mark');mark.append(range.extractContents());range.insertNode(mark);sel.removeAllRanges();$('#studio-status').textContent='Matn belgilandi.';};$('#studio-clear').onclick=()=>$('#studio-passage').querySelectorAll('mark').forEach(m=>m.replaceWith(...m.childNodes));}
}
